//! CodeYourPCB Design Rule Check (DRC) Engine
//!
//! Validates PCB designs against manufacturer constraints before fabrication.
//! Uses the spatial index for efficient clearance checking with O(log n) queries.
//!
//! # Architecture
//!
//! DRC rules are implemented as structs that implement the [`DrcRule`] trait.
//! The engine runs all enabled rules against the board and collects violations.
//!
//! # Usage
//!
//! ```rust,ignore
//! use cypcb_drc::{run_drc, DesignRules, DrcResult, Preset};
//! use cypcb_world::BoardWorld;
//!
//! let world = BoardWorld::new();
//! // ... load board ...
//!
//! // Use a manufacturer preset
//! let rules = DesignRules::jlcpcb_2layer();
//! let result = run_drc(&world, &rules);
//!
//! // Or lookup by name (from DSL parsing)
//! let preset = Preset::from_name("pcbway").unwrap();
//! let rules = preset.rules();
//!
//! if result.passed() {
//!     println!("Board passes DRC!");
//! } else {
//!     println!("{} violations found", result.violation_count());
//!     for violation in &result.violations {
//!         println!("  {}: {}", violation.kind, violation.message);
//!     }
//! }
//! ```

pub mod presets;
pub mod rules;
pub mod violation;

pub use presets::{DesignRules, Preset};
pub use rules::DrcRule;
pub use violation::{DrcViolation, ViolationKind};

use cypcb_world::BoardWorld;

/// Result of running DRC on a board.
#[derive(Debug, Clone)]
pub struct DrcResult {
    /// List of violations found.
    pub violations: Vec<DrcViolation>,
    /// Time taken to run DRC in milliseconds (for performance tracking).
    pub duration_ms: u64,
}

impl DrcResult {
    /// Check if the board passed all checks.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DrcResult;
    ///
    /// let result = DrcResult { violations: vec![], duration_ms: 10 };
    /// assert!(result.passed());
    /// ```
    pub fn passed(&self) -> bool {
        self.violations.is_empty()
    }

    /// Number of violations found.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DrcResult;
    ///
    /// let result = DrcResult { violations: vec![], duration_ms: 10 };
    /// assert_eq!(result.violation_count(), 0);
    /// ```
    pub fn violation_count(&self) -> usize {
        self.violations.len()
    }
}

impl Default for DrcResult {
    fn default() -> Self {
        DrcResult {
            violations: Vec::new(),
            duration_ms: 0,
        }
    }
}

/// Run DRC on a board world.
///
/// Executes all enabled rules against the board and returns accumulated violations.
///
/// # Arguments
///
/// * `world` - The board world to check (mutable for ECS queries)
/// * `rules` - Design rules to check against
///
/// # Returns
///
/// DrcResult with all violations found.
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::{run_drc, DesignRules};
/// use cypcb_world::BoardWorld;
///
/// let mut world = BoardWorld::new();
/// let rules = DesignRules::default();
/// let result = run_drc(&mut world, &rules);
/// println!("DRC completed in {}ms", result.duration_ms);
/// ```
pub fn run_drc(world: &mut BoardWorld, rules: &DesignRules) -> DrcResult {
    // Timing - skip in WASM (Instant may not work reliably)
    #[cfg(not(target_arch = "wasm32"))]
    let start = std::time::Instant::now();

    let mut violations = Vec::new();

    // Create all rule checkers
    let checkers: Vec<Box<dyn DrcRule>> = vec![
        Box::new(rules::ClearanceRule),
        Box::new(rules::MinDrillSizeRule),
        Box::new(rules::MinTraceWidthRule),  // Placeholder - returns empty until traces exist
        Box::new(rules::UnconnectedPinRule),
        Box::new(rules::KeepoutRule),
    ];

    // Run each checker
    for checker in &checkers {
        violations.extend(checker.check(world, rules));
    }

    #[cfg(not(target_arch = "wasm32"))]
    let duration_ms = start.elapsed().as_millis() as u64;
    #[cfg(target_arch = "wasm32")]
    let duration_ms = 0; // Skip timing in WASM

    DrcResult {
        violations,
        duration_ms,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_drc_result_passed_empty() {
        let result = DrcResult::default();
        assert!(result.passed());
        assert_eq!(result.violation_count(), 0);
    }

    #[test]
    fn test_drc_result_with_violations() {
        use cypcb_core::Point;
        use bevy_ecs::entity::Entity;

        let result = DrcResult {
            violations: vec![
                DrcViolation::unconnected_pin(
                    Entity::from_raw(1),
                    "1",
                    "R1",
                    Point::ORIGIN,
                ),
            ],
            duration_ms: 5,
        };

        assert!(!result.passed());
        assert_eq!(result.violation_count(), 1);
    }

    #[test]
    fn test_run_drc_empty_world() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();
        let result = run_drc(&mut world, &rules);

        // Empty world should have no violations
        assert!(result.passed());
    }
}

//! DRC rule definitions and implementations.
//!
//! This module defines the [`DrcRule`] trait that all rules implement.
//! Design rules configuration is defined in the [`presets`](crate::presets) module.

pub mod clearance;
pub mod connectivity;
pub mod drill_size;
pub mod trace_width;

use cypcb_world::BoardWorld;

use crate::presets::DesignRules;
use crate::violation::DrcViolation;

pub use clearance::ClearanceRule;
pub use connectivity::UnconnectedPinRule;
pub use drill_size::MinDrillSizeRule;
pub use trace_width::MinTraceWidthRule;

/// A single DRC rule that can be executed against a board.
///
/// Rules are implemented as structs that hold no state. Configuration
/// comes from the [`DesignRules`] struct passed to `check()`.
///
/// # Object Safety
///
/// This trait is designed to be object-safe, allowing rules to be
/// stored in a `Vec<Box<dyn DrcRule>>` for flexible rule composition.
///
/// # Examples
///
/// ```rust,ignore
/// impl DrcRule for ClearanceRule {
///     fn name(&self) -> &'static str {
///         "clearance"
///     }
///
///     fn check(&self, world: &BoardWorld, rules: &DesignRules) -> Vec<DrcViolation> {
///         // Implementation...
///         vec![]
///     }
/// }
/// ```
pub trait DrcRule: Send + Sync {
    /// Rule identifier for error messages and filtering.
    fn name(&self) -> &'static str;

    /// Execute the rule check against the board world.
    ///
    /// Returns a list of violations (empty if rule passes).
    ///
    /// # Arguments
    ///
    /// * `world` - The board world to check (mutable for ECS queries)
    /// * `rules` - Design rules configuration
    ///
    /// Note: Takes `&mut BoardWorld` because bevy_ecs queries need to
    /// initialize their cache. No actual board data is modified.
    fn check(&self, world: &mut BoardWorld, rules: &DesignRules) -> Vec<DrcViolation>;
}

/// Rule for checking components against keepout zones.
///
/// This rule checks if any component's position falls within a keepout zone.
/// Note: Currently only checks center point - a more complete implementation
/// would check the entire component footprint bounds.
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::rules::KeepoutRule;
/// use cypcb_drc::rules::DrcRule;
///
/// let rule = KeepoutRule;
/// let violations = rule.check(&world, &rules);
/// for v in violations {
///     println!("Keepout violation: {}", v.message);
/// }
/// ```
pub struct KeepoutRule;

impl DrcRule for KeepoutRule {
    fn name(&self) -> &'static str {
        "keepout"
    }

    fn check(&self, world: &mut BoardWorld, _rules: &DesignRules) -> Vec<DrcViolation> {
        let mut violations = Vec::new();

        // Collect all keepout zones
        let zones: Vec<_> = world.zones()
            .into_iter()
            .filter(|(_, zone)| zone.is_keepout())
            .collect();

        // If no keepout zones, skip
        if zones.is_empty() {
            return violations;
        }

        // Collect all components
        let components = world.components();

        // Check each component against keepout zones
        for (entity, refdes, position) in components {
            for (zone_entity, zone) in &zones {
                // Check if component center is inside zone
                if zone.contains(position.0) {
                    violations.push(DrcViolation::keepout(
                        entity,
                        *zone_entity,
                        refdes.as_str(),
                        zone.name.as_deref(),
                        position.0,
                    ));
                }
            }
        }

        violations
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use cypcb_core::{Point, Rect};
    use cypcb_world::components::{FootprintRef, NetConnections, Position, RefDes, Rotation, Value, Zone};
    use cypcb_world::components::zone::ZoneKind;
    use crate::ViolationKind;

    #[test]
    fn test_trait_object_safe() {
        // Verify that DrcRule can be used as a trait object
        fn _assert_object_safe(_: &dyn DrcRule) {}
    }

    #[test]
    fn test_rule_names() {
        assert_eq!(ClearanceRule.name(), "clearance");
        assert_eq!(MinDrillSizeRule.name(), "min-drill-size");
        assert_eq!(MinTraceWidthRule.name(), "min-trace-width");
        assert_eq!(UnconnectedPinRule.name(), "unconnected-pin");
        assert_eq!(KeepoutRule.name(), "keepout");
    }

    #[test]
    fn test_rule_check_empty_world() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // All rules should return empty on empty world
        assert!(ClearanceRule.check(&mut world, &rules).is_empty());
        assert!(MinDrillSizeRule.check(&mut world, &rules).is_empty());
        assert!(MinTraceWidthRule.check(&mut world, &rules).is_empty());
        assert!(UnconnectedPinRule.check(&mut world, &rules).is_empty());
        assert!(KeepoutRule.check(&mut world, &rules).is_empty());
    }

    #[test]
    fn test_rule_trait_object_vec() {
        // Verify rules can be collected into a Vec<Box<dyn DrcRule>>
        let rules: Vec<Box<dyn DrcRule>> = vec![
            Box::new(ClearanceRule),
            Box::new(MinDrillSizeRule),
            Box::new(MinTraceWidthRule),
            Box::new(UnconnectedPinRule),
            Box::new(KeepoutRule),
        ];
        assert_eq!(rules.len(), 5);
        assert_eq!(rules[0].name(), "clearance");
        assert_eq!(rules[1].name(), "min-drill-size");
        assert_eq!(rules[2].name(), "min-trace-width");
        assert_eq!(rules[3].name(), "unconnected-pin");
        assert_eq!(rules[4].name(), "keepout");
    }

    #[test]
    fn test_keepout_rule_detects_violation() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a keepout zone
        let zone = Zone {
            bounds: Rect::new(
                Point::from_mm(10.0, 10.0),
                Point::from_mm(20.0, 20.0),
            ),
            kind: ZoneKind::Keepout,
            layer_mask: 0xFFFFFFFF,
            name: Some("test_zone".to_string()),
        };
        world.ecs_mut().spawn(zone);

        // Create a component inside the zone
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(15.0, 15.0), // Inside zone
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Run the rule
        let violations = KeepoutRule.check(&mut world, &rules);
        assert_eq!(violations.len(), 1, "expected 1 violation");
        assert_eq!(violations[0].kind, ViolationKind::KeepoutViolation);
        assert!(violations[0].message.contains("R1"));
        assert!(violations[0].message.contains("test_zone"));
    }

    #[test]
    fn test_keepout_rule_no_violation_outside() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a keepout zone
        let zone = Zone {
            bounds: Rect::new(
                Point::from_mm(10.0, 10.0),
                Point::from_mm(20.0, 20.0),
            ),
            kind: ZoneKind::Keepout,
            layer_mask: 0xFFFFFFFF,
            name: Some("test_zone".to_string()),
        };
        world.ecs_mut().spawn(zone);

        // Create a component outside the zone
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(5.0, 5.0), // Outside zone
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Run the rule
        let violations = KeepoutRule.check(&mut world, &rules);
        assert!(violations.is_empty(), "expected no violations");
    }

    #[test]
    fn test_keepout_rule_ignores_copper_pour_zones() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a copper pour zone (not keepout)
        let zone = Zone {
            bounds: Rect::new(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(50.0, 50.0),
            ),
            kind: ZoneKind::CopperPour,
            layer_mask: 0xFFFFFFFF,
            name: Some("gnd_pour".to_string()),
        };
        world.ecs_mut().spawn(zone);

        // Create a component inside the copper pour zone
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(15.0, 15.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Run the rule - should not detect violation (copper pour is not keepout)
        let violations = KeepoutRule.check(&mut world, &rules);
        assert!(violations.is_empty(), "copper pour zones should not trigger keepout violations");
    }

    #[test]
    fn test_keepout_rule_multiple_components() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a keepout zone
        let zone = Zone {
            bounds: Rect::new(
                Point::from_mm(10.0, 10.0),
                Point::from_mm(20.0, 20.0),
            ),
            kind: ZoneKind::Keepout,
            layer_mask: 0xFFFFFFFF,
            name: None,
        };
        world.ecs_mut().spawn(zone);

        // Component inside
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(15.0, 15.0), // Inside
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Component outside
        world.spawn_component(
            RefDes::new("R2"),
            Value::new("10k"),
            Position::from_mm(5.0, 5.0), // Outside
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Another component inside
        world.spawn_component(
            RefDes::new("R3"),
            Value::new("10k"),
            Position::from_mm(12.0, 18.0), // Inside
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Run the rule
        let violations = KeepoutRule.check(&mut world, &rules);
        assert_eq!(violations.len(), 2, "expected 2 violations (R1 and R3)");

        // Verify both violations are for the right components
        let refdes_list: Vec<_> = violations.iter()
            .map(|v| v.message.clone())
            .collect();
        assert!(refdes_list.iter().any(|m| m.contains("R1")));
        assert!(refdes_list.iter().any(|m| m.contains("R3")));
        assert!(!refdes_list.iter().any(|m| m.contains("R2")));
    }
}

//! Manufacturer preset design rules.
//!
//! This module provides pre-configured design rules for common PCB manufacturers.
//! Use the [`Preset`] enum for name-based lookup or call the constructor methods
//! directly on [`DesignRules`].
//!
//! # Supported Manufacturers
//!
//! - **JLCPCB**: Popular Chinese manufacturer with competitive pricing
//!   - 2-layer: Standard hobbyist option with 6mil minimum
//!   - 4-layer: Tighter tolerances available (4mil)
//!
//! - **PCBWay**: Alternative Chinese manufacturer with similar capabilities
//!
//! - **Prototype**: Relaxed rules for prototyping and hand assembly
//!
//! # Examples
//!
//! ```
//! use cypcb_drc::presets::{DesignRules, Preset};
//!
//! // Use preset enum for dynamic lookup
//! let preset = Preset::from_name("jlcpcb").unwrap();
//! let rules = preset.rules();
//!
//! // Or use constructor directly
//! let rules = DesignRules::jlcpcb_2layer();
//! ```

mod jlcpcb;
mod pcbway;

use cypcb_core::Nm;

/// Complete set of design rules for a board.
///
/// Contains minimum values for various design parameters that the DRC engine
/// validates against. Use the factory methods for manufacturer presets, or
/// create custom rules by constructing directly.
///
/// # Fields
///
/// - `min_clearance`: Minimum distance between copper features on the same layer
/// - `min_trace_width`: Minimum width of copper traces
/// - `min_drill_size`: Minimum mechanical drill hole diameter
/// - `min_via_drill`: Minimum via drill hole diameter
/// - `min_annular_ring`: Minimum width of copper ring around drill holes
/// - `min_silk_width`: Minimum silkscreen line width
/// - `min_edge_clearance`: Minimum distance from copper to board edge
///
/// # Examples
///
/// ```
/// use cypcb_drc::presets::DesignRules;
/// use cypcb_core::Nm;
///
/// // Use a manufacturer preset
/// let jlcpcb = DesignRules::jlcpcb_2layer();
/// assert_eq!(jlcpcb.min_clearance, Nm::from_mm(0.15));
///
/// // Or create custom rules
/// let custom = DesignRules {
///     min_clearance: Nm::from_mm(0.2),
///     min_trace_width: Nm::from_mm(0.25),
///     min_drill_size: Nm::from_mm(0.4),
///     min_via_drill: Nm::from_mm(0.3),
///     min_annular_ring: Nm::from_mm(0.2),
///     min_silk_width: Nm::from_mm(0.2),
///     min_edge_clearance: Nm::from_mm(0.5),
/// };
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesignRules {
    /// Minimum clearance between copper features.
    pub min_clearance: Nm,
    /// Minimum trace width.
    pub min_trace_width: Nm,
    /// Minimum drill size (mechanical drilling).
    pub min_drill_size: Nm,
    /// Minimum via drill size.
    pub min_via_drill: Nm,
    /// Minimum annular ring width.
    pub min_annular_ring: Nm,
    /// Minimum silkscreen line width.
    pub min_silk_width: Nm,
    /// Minimum copper to board edge clearance.
    pub min_edge_clearance: Nm,
}

impl Default for DesignRules {
    /// Default rules use JLCPCB 2-layer values.
    ///
    /// JLCPCB is chosen as default because it's the most commonly used
    /// manufacturer for hobbyist PCB fabrication.
    fn default() -> Self {
        Self::jlcpcb_2layer()
    }
}

/// Manufacturer preset identifiers.
///
/// Use [`from_name`](Preset::from_name) for string-based lookup (useful for
/// DSL parsing) or match directly on the enum variants.
///
/// # Examples
///
/// ```
/// use cypcb_drc::presets::Preset;
///
/// // From string (e.g., parsed from DSL)
/// let preset = Preset::from_name("jlcpcb").unwrap();
/// assert_eq!(preset, Preset::Jlcpcb2Layer);
///
/// // Get rules from preset
/// let rules = preset.rules();
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Preset {
    /// JLCPCB standard 2-layer board.
    Jlcpcb2Layer,
    /// JLCPCB 4-layer board with tighter tolerances.
    Jlcpcb4Layer,
    /// PCBWay standard capabilities.
    PcbwayStandard,
    /// Relaxed rules for prototyping.
    Prototype,
}

impl Preset {
    /// Get the design rules for this preset.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    /// use cypcb_core::Nm;
    ///
    /// let rules = Preset::Jlcpcb2Layer.rules();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
    /// ```
    pub fn rules(self) -> DesignRules {
        match self {
            Preset::Jlcpcb2Layer => DesignRules::jlcpcb_2layer(),
            Preset::Jlcpcb4Layer => DesignRules::jlcpcb_4layer(),
            Preset::PcbwayStandard => DesignRules::pcbway_standard(),
            Preset::Prototype => DesignRules::prototype(),
        }
    }

    /// Parse a preset from a string name.
    ///
    /// Accepts various aliases for convenience:
    /// - `"jlcpcb"` or `"jlcpcb_2layer"` -> [`Jlcpcb2Layer`](Preset::Jlcpcb2Layer)
    /// - `"jlcpcb_4layer"` -> [`Jlcpcb4Layer`](Preset::Jlcpcb4Layer)
    /// - `"pcbway"` or `"pcbway_standard"` -> [`PcbwayStandard`](Preset::PcbwayStandard)
    /// - `"prototype"` -> [`Prototype`](Preset::Prototype)
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// assert_eq!(Preset::from_name("jlcpcb"), Some(Preset::Jlcpcb2Layer));
    /// assert_eq!(Preset::from_name("jlcpcb_2layer"), Some(Preset::Jlcpcb2Layer));
    /// assert_eq!(Preset::from_name("pcbway"), Some(Preset::PcbwayStandard));
    /// assert_eq!(Preset::from_name("unknown"), None);
    /// ```
    pub fn from_name(name: &str) -> Option<Self> {
        match name {
            "jlcpcb" | "jlcpcb_2layer" => Some(Preset::Jlcpcb2Layer),
            "jlcpcb_4layer" => Some(Preset::Jlcpcb4Layer),
            "pcbway" | "pcbway_standard" => Some(Preset::PcbwayStandard),
            "prototype" => Some(Preset::Prototype),
            _ => None,
        }
    }

    /// Get the canonical name for this preset.
    ///
    /// Returns the primary string identifier used in DSL files.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// assert_eq!(Preset::Jlcpcb2Layer.name(), "jlcpcb_2layer");
    /// assert_eq!(Preset::PcbwayStandard.name(), "pcbway_standard");
    /// ```
    pub fn name(self) -> &'static str {
        match self {
            Preset::Jlcpcb2Layer => "jlcpcb_2layer",
            Preset::Jlcpcb4Layer => "jlcpcb_4layer",
            Preset::PcbwayStandard => "pcbway_standard",
            Preset::Prototype => "prototype",
        }
    }

    /// Get all available presets.
    ///
    /// Useful for generating documentation or CLI help text.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::presets::Preset;
    ///
    /// let presets = Preset::all();
    /// assert_eq!(presets.len(), 4);
    /// ```
    pub fn all() -> &'static [Preset] {
        &[
            Preset::Jlcpcb2Layer,
            Preset::Jlcpcb4Layer,
            Preset::PcbwayStandard,
            Preset::Prototype,
        ]
    }
}

impl std::fmt::Display for Preset {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.name())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_jlcpcb_2layer_values() {
        let rules = DesignRules::jlcpcb_2layer();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(rules.min_via_drill, Nm::from_mm(0.2));
        assert_eq!(rules.min_annular_ring, Nm::from_mm(0.15));
