        );

        // 3A, 1oz, external, 10C rise: ~50 mils
        let result = TraceWidthCalculator::calculate(&TraceWidthParams::new(3.0));
        assert!(
            within_percent(result.width_mil(), 50.0, 30.0),
            "3A should be ~50 mils, got {} mils",
            result.width_mil()
        );

        // 5A, 1oz, external, 10C rise: ~110 mils
        let result = TraceWidthCalculator::calculate(&TraceWidthParams::new(5.0));
        assert!(
            within_percent(result.width_mil(), 110.0, 30.0),
            "5A should be ~110 mils, got {} mils",
            result.width_mil()
        );
    }

    #[test]
    fn test_warning_display() {
        // Ensure Display trait works for warnings
        let warnings = vec![
            TraceWidthWarning::CurrentTooHigh,
            TraceWidthWarning::TempRiseTooLow,
            TraceWidthWarning::TempRiseTooHigh,
            TraceWidthWarning::WidthExceedsMax,
            TraceWidthWarning::CopperWeightNonStandard,
        ];

        for warning in warnings {
            let msg = format!("{}", warning);
            assert!(!msg.is_empty());
        }
    }
}

//! Unit types for dimension parsing.
//!
//! This module provides the [`Unit`] enum for representing and converting
//! between different measurement units used in PCB design.

use crate::coords::{Nm, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use thiserror::Error;

/// A unit of measurement for PCB dimensions.
///
/// Used for parsing dimensions from the DSL and converting to internal
/// nanometer representation.
///
/// # Examples
///
/// ```
/// use cypcb_core::{Unit, Nm};
///
/// let unit = Unit::Mm;
/// let nm = unit.to_nm(10.0);
/// assert_eq!(nm.0, 10_000_000);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Unit {
    /// Millimeters (1 mm = 1,000,000 nm)
    Mm,
    /// Mils / thousandths of an inch (1 mil = 25,400 nm)
    Mil,
    /// Inches (1 inch = 25,400,000 nm)
    Inch,
    /// Nanometers (native unit)
    Nm,
}

impl Unit {
    /// Convert a value in this unit to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
    /// assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
    /// assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
    /// assert_eq!(Unit::Nm.to_nm(100.0).0, 100);
    /// ```
    #[inline]
    pub fn to_nm(self, value: f64) -> Nm {
        let nm = match self {
            Unit::Mm => (value * NM_PER_MM as f64).round() as i64,
            Unit::Mil => (value * NM_PER_MIL as f64).round() as i64,
            Unit::Inch => (value * NM_PER_INCH as f64).round() as i64,
            Unit::Nm => value.round() as i64,
        };
        Nm(nm)
    }

    /// Convert a nanometer value to this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::{Unit, Nm};
    ///
    /// let nm = Nm(1_000_000);
    /// assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);
    /// ```
    #[inline]
    pub fn from_nm(self, nm: Nm) -> f64 {
        match self {
            Unit::Mm => nm.0 as f64 / NM_PER_MM as f64,
            Unit::Mil => nm.0 as f64 / NM_PER_MIL as f64,
            Unit::Inch => nm.0 as f64 / NM_PER_INCH as f64,
            Unit::Nm => nm.0 as f64,
        }
    }

    /// Get the suffix string for this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.suffix(), "mm");
    /// assert_eq!(Unit::Mil.suffix(), "mil");
    /// ```
    pub const fn suffix(self) -> &'static str {
        match self {
            Unit::Mm => "mm",
            Unit::Mil => "mil",
            Unit::Inch => "in",
            Unit::Nm => "nm",
        }
    }

    /// Get the nanometers per unit.
    ///
    /// Returns 1 for nanometers.
    pub const fn nm_per_unit(self) -> i64 {
        match self {
            Unit::Mm => NM_PER_MM,
            Unit::Mil => NM_PER_MIL,
            Unit::Inch => NM_PER_INCH,
            Unit::Nm => 1,
        }
    }
}

impl Default for Unit {
    fn default() -> Self {
        Unit::Mm
    }
}

impl std::fmt::Display for Unit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.suffix())
    }
}

/// Error type for unit parsing.
#[derive(Debug, Clone, Error, PartialEq, Eq)]
#[error("unknown unit: '{0}' (expected: mm, mil, in, nm)")]
pub struct ParseUnitError(pub String);

impl FromStr for Unit {
    type Err = ParseUnitError;

    /// Parse a unit from a string.
    ///
    /// Accepts: "mm", "mil", "in", "inch", "nm"
    /// Case-insensitive.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
    /// assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
    /// assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    ///
    /// // Case insensitive
    /// assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
    /// ```
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "mm" => Ok(Unit::Mm),
            "mil" | "mils" => Ok(Unit::Mil),
            "in" | "inch" | "inches" => Ok(Unit::Inch),
            "nm" => Ok(Unit::Nm),
            _ => Err(ParseUnitError(s.to_string())),
        }
    }
}

/// A dimension value with an associated unit.
///
/// This is useful for preserving the original unit in the source
/// while still being able to convert to nanometers.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Dimension {
    /// The numeric value in the original unit.
    pub value: f64,
    /// The unit of measurement.
    pub unit: Unit,
}

impl Dimension {
    /// Create a new dimension.
    pub const fn new(value: f64, unit: Unit) -> Self {
        Dimension { value, unit }
    }

    /// Create a dimension in millimeters.
    pub const fn mm(value: f64) -> Self {
        Dimension { value, unit: Unit::Mm }
    }

    /// Create a dimension in mils.
    pub const fn mil(value: f64) -> Self {
        Dimension { value, unit: Unit::Mil }
    }

    /// Create a dimension in inches.
    pub const fn inch(value: f64) -> Self {
        Dimension { value, unit: Unit::Inch }
    }

    /// Create a dimension in nanometers.
    pub const fn nm(value: f64) -> Self {
        Dimension { value, unit: Unit::Nm }
    }

    /// Convert this dimension to nanometers.
    pub fn to_nm(self) -> Nm {
        self.unit.to_nm(self.value)
    }
}

impl std::fmt::Display for Dimension {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_unit_to_nm() {
        assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
        assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
        assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
        assert_eq!(Unit::Nm.to_nm(1.0).0, 1);
    }

    #[test]
    fn test_unit_from_nm() {
        let nm = Nm(1_000_000);
        assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400);
        assert!((Unit::Mil.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400_000);
        assert!((Unit::Inch.from_nm(nm) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn test_unit_round_trip() {
        for unit in [Unit::Mm, Unit::Mil, Unit::Inch] {
            let original = 10.5;
            let nm = unit.to_nm(original);
            let back = unit.from_nm(nm);
            assert!((back - original).abs() < 0.001, "Round-trip failed for {:?}", unit);
        }
    }

    #[test]
    fn test_unit_parse() {
        assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("mils".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inches".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    }

    #[test]
    fn test_unit_parse_error() {
        let result = "cm".parse::<Unit>();
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().0, "cm");
    }

    #[test]
    fn test_dimension_to_nm() {
        let dim = Dimension::mm(10.0);
        assert_eq!(dim.to_nm().0, 10_000_000);

        let dim = Dimension::mil(100.0);
        assert_eq!(dim.to_nm().0, 2_540_000);
    }

    #[test]
    fn test_unit_suffix() {
        assert_eq!(Unit::Mm.suffix(), "mm");
        assert_eq!(Unit::Mil.suffix(), "mil");
        assert_eq!(Unit::Inch.suffix(), "in");
        assert_eq!(Unit::Nm.suffix(), "nm");
    }
}

//! JLCPCB manufacturer design rules.
//!
//! JLCPCB is a popular Chinese PCB manufacturer known for competitive pricing
//! and fast turnaround. Their capabilities are well-documented and suitable
//! for most hobbyist and professional projects.
//!
//! # Sources
//!
//! - <https://jlcpcb.com/capabilities/pcb-capabilities>
//! - <https://www.schemalyzer.com/en/blog/manufacturing/jlcpcb/jlcpcb-design-rules>

use super::DesignRules;
use cypcb_core::Nm;

impl DesignRules {
    /// JLCPCB standard 2-layer board rules.
    ///
    /// These are the most common rules for hobbyist projects. The 6mil (0.15mm)
    /// minimum is achievable at standard pricing.
    ///
    /// # Specifications
    ///
    /// | Parameter | Value | Notes |
    /// |-----------|-------|-------|
    /// | Min clearance | 0.15mm (6 mil) | Standard tolerance |
    /// | Min trace width | 0.15mm (6 mil) | Standard tolerance |
    /// | Min drill | 0.3mm | Mechanical drilling |
    /// | Min via drill | 0.2mm | Via holes |
    /// | Min annular ring | 0.15mm (6 mil) | Copper around drill |
    /// | Min silk width | 0.15mm (6 mil) | Silkscreen lines |
    /// | Min edge clearance | 0.3mm | Copper to board edge |
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DesignRules;
    /// use cypcb_core::Nm;
    ///
    /// let rules = DesignRules::jlcpcb_2layer();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
    /// assert_eq!(rules.min_drill_size, Nm::from_mm(0.3));
    /// ```
    pub fn jlcpcb_2layer() -> Self {
        DesignRules {
            min_clearance: Nm::from_mm(0.15),       // 6 mil
            min_trace_width: Nm::from_mm(0.15),     // 6 mil
            min_drill_size: Nm::from_mm(0.3),       // 0.3mm mechanical
            min_via_drill: Nm::from_mm(0.2),        // 0.2mm via
            min_annular_ring: Nm::from_mm(0.15),    // 6 mil
            min_silk_width: Nm::from_mm(0.15),      // 6 mil
            min_edge_clearance: Nm::from_mm(0.3),   // 0.3mm
        }
    }

    /// JLCPCB 4-layer board rules with tighter tolerances.
    ///
    /// 4-layer boards have access to tighter tolerances due to better
    /// manufacturing control. The 4mil (0.1mm) minimum is available
    /// at slightly higher cost.
    ///
    /// # Specifications
    ///
    /// | Parameter | Value | Notes |
    /// |-----------|-------|-------|
    /// | Min clearance | 0.1mm (4 mil) | Tighter tolerance |
    /// | Min trace width | 0.1mm (4 mil) | Tighter tolerance |
    /// | Min drill | 0.2mm | Smaller drills available |
    /// | Min via drill | 0.2mm | Via holes |
    /// | Min annular ring | 0.125mm (5 mil) | Tighter tolerance |
    /// | Min silk width | 0.15mm (6 mil) | Same as 2-layer |
    /// | Min edge clearance | 0.25mm | Tighter than 2-layer |
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DesignRules;
    /// use cypcb_core::Nm;
    ///
    /// let rules = DesignRules::jlcpcb_4layer();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.1));
    /// assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
    /// ```
    pub fn jlcpcb_4layer() -> Self {
        DesignRules {
            min_clearance: Nm::from_mm(0.1),        // 4 mil
            min_trace_width: Nm::from_mm(0.1),      // 4 mil
            min_drill_size: Nm::from_mm(0.2),       // 0.2mm
            min_via_drill: Nm::from_mm(0.2),
            min_annular_ring: Nm::from_mm(0.125),   // 5 mil
            min_silk_width: Nm::from_mm(0.15),
            min_edge_clearance: Nm::from_mm(0.25),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_jlcpcb_2layer_clearance() {
        let rules = DesignRules::jlcpcb_2layer();
        // 6 mil = 0.1524mm, rounded to 0.15mm
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
    }

    #[test]
    fn test_jlcpcb_2layer_drill() {
        let rules = DesignRules::jlcpcb_2layer();
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(rules.min_via_drill, Nm::from_mm(0.2));
    }

    #[test]
    fn test_jlcpcb_4layer_tighter() {
        let two = DesignRules::jlcpcb_2layer();
        let four = DesignRules::jlcpcb_4layer();

        // 4-layer should have tighter (smaller) minimums
        assert!(four.min_clearance < two.min_clearance);
        assert!(four.min_trace_width < two.min_trace_width);
        assert!(four.min_drill_size < two.min_drill_size);
        assert!(four.min_annular_ring < two.min_annular_ring);
        assert!(four.min_edge_clearance < two.min_edge_clearance);
    }

    #[test]
    fn test_jlcpcb_2layer_all_fields() {
        let rules = DesignRules::jlcpcb_2layer();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(rules.min_via_drill, Nm::from_mm(0.2));
        assert_eq!(rules.min_annular_ring, Nm::from_mm(0.15));
        assert_eq!(rules.min_silk_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_edge_clearance, Nm::from_mm(0.3));
    }

    #[test]
    fn test_jlcpcb_4layer_all_fields() {
        let rules = DesignRules::jlcpcb_4layer();
        assert_eq!(rules.min_clearance, Nm::from_mm(0.1));
        assert_eq!(rules.min_trace_width, Nm::from_mm(0.1));
        assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
        assert_eq!(rules.min_via_drill, Nm::from_mm(0.2));
        assert_eq!(rules.min_annular_ring, Nm::from_mm(0.125));
        assert_eq!(rules.min_silk_width, Nm::from_mm(0.15));
        assert_eq!(rules.min_edge_clearance, Nm::from_mm(0.25));
    }
}

//! PCBWay manufacturer design rules.
//!
//! PCBWay is a Chinese PCB manufacturer with similar capabilities to JLCPCB.
//! They offer competitive pricing and good quality for both hobbyist and
//! professional projects.
//!
//! # Sources
//!
//! - <https://www.pcbway.com/capabilities.html>

use super::DesignRules;
use cypcb_core::Nm;

impl DesignRules {
    /// PCBWay standard rules.
    ///
    /// These rules represent PCBWay's recommended minimums for standard
    /// pricing. While they can achieve 3mil in some cases, 6mil is recommended
    /// for reliable results.
    ///
    /// # Specifications
    ///
    /// | Parameter | Value | Notes |
    /// |-----------|-------|-------|
    /// | Min clearance | 0.15mm (6 mil) | Recommended |
    /// | Min trace width | 0.15mm (6 mil) | Recommended |
    /// | Min drill | 0.2mm | Mechanical drilling |
    /// | Min via drill | 0.2mm | Via holes |
    /// | Min annular ring | 0.15mm (6 mil) | Copper around drill |
    /// | Min silk width | 0.22mm (8.66 mil) | Wider than JLCPCB |
    /// | Min edge clearance | 0.3mm | Copper to board edge |
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DesignRules;
    /// use cypcb_core::Nm;
    ///
    /// let rules = DesignRules::pcbway_standard();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.15));
    /// assert_eq!(rules.min_drill_size, Nm::from_mm(0.2));
    /// ```
    pub fn pcbway_standard() -> Self {
        DesignRules {
            min_clearance: Nm::from_mm(0.15),       // 6 mil recommended
            min_trace_width: Nm::from_mm(0.15),
            min_drill_size: Nm::from_mm(0.2),       // Mechanical
            min_via_drill: Nm::from_mm(0.2),
            min_annular_ring: Nm::from_mm(0.15),
            min_silk_width: Nm::from_mm(0.22),      // 8.66 mil - wider than JLCPCB
            min_edge_clearance: Nm::from_mm(0.3),
        }
    }

    /// Relaxed rules for prototyping.
    ///
    /// These rules provide larger margins for hand-soldering, beginner designs,
    /// or when using lower-quality fabrication services. Using larger minimums
    /// increases yield and reduces manufacturing issues.
    ///
    /// # Specifications
    ///
    /// | Parameter | Value | Notes |
    /// |-----------|-------|-------|
    /// | Min clearance | 0.2mm (8 mil) | Conservative |
    /// | Min trace width | 0.25mm (10 mil) | Easier soldering |
    /// | Min drill | 0.4mm | Larger holes |
    /// | Min via drill | 0.3mm | Larger vias |
    /// | Min annular ring | 0.2mm (8 mil) | More copper |
    /// | Min silk width | 0.2mm (8 mil) | Readable text |
    /// | Min edge clearance | 0.5mm | Safe margin |
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::DesignRules;
    /// use cypcb_core::Nm;
    ///
    /// let rules = DesignRules::prototype();
    /// assert_eq!(rules.min_clearance, Nm::from_mm(0.2));
    /// assert_eq!(rules.min_trace_width, Nm::from_mm(0.25));
    /// ```
    pub fn prototype() -> Self {
        DesignRules {
            min_clearance: Nm::from_mm(0.2),        // 8 mil
            min_trace_width: Nm::from_mm(0.25),     // 10 mil
            min_drill_size: Nm::from_mm(0.4),
